using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Xml.Serialization;using MakroSoundSwitch;
class FakeBackend:IFeatureBackend {
 public List<string> Log=new List<string>();public string[,] Defaults=new string[,]{{"out0","out1","out2"},{"in0","in1","in2"}};public int Lists;public string FailId;
 public List<Device> ListDevices(int flow){Lists++;return new List<Device>{new Device{Id=flow==0?"speaker":"mic",Name="Device"}};}
 public string GetDefault(int f,int r){return Defaults[f,r];}public void SetDefault(string id,int r){Log.Add(id+":"+r);if(id==FailId)throw new Exception("Simulated switch failure");Defaults[id.StartsWith("in")||id=="mic"?1:0,r]=id;}public void SendMedia(FeatureType t){Log.Add(t.ToString());}public void Mute(){Log.Add("Mute");}
}
class Receiver:Form {public int Command;protected override void WndProc(ref Message m){if(m.Msg==0x319){Command=(int)((m.LParam.ToInt64()>>16)&0x7ff);m.Result=(IntPtr)1;return;}base.WndProc(ref m);}}
class FeatureVerify {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Assert(bool b,string m){if(!b)throw new Exception(m);Console.WriteLine("PASS: "+m);}
 static ScenarioFeature A(FeatureType t,string id=""){return new ScenarioFeature{Type=t,DeviceId=id};}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
 var legacy=new Scenario{Output="speaker",Input="mic"};Assert(Features.For(legacy).Select(f=>f.Type).SequenceEqual(new[]{FeatureType.Output,FeatureType.Input}),"Legacy scenarios migrate to Output and Input features");var serializer=new XmlSerializer(typeof(Scenario));Scenario loaded;using(var stream=new MemoryStream()){serializer.Serialize(stream,legacy);stream.Position=0;loaded=(Scenario)serializer.Deserialize(stream);}Assert(Features.For(loaded).Count==2,"Legacy scenario migration survives XML deserialization");
 var scenario=new Scenario{Name="Headset + playback",Chord=new List<int>{17,18,16,75,76},Features=new List<ScenarioFeature>{A(FeatureType.Output,"speaker"),A(FeatureType.Input,"mic"),A(FeatureType.PlayMedia),A(FeatureType.NextMedia),A(FeatureType.PauseMedia),A(FeatureType.PreviousMedia),A(FeatureType.MuteMedia)}};
 using(var stream=new MemoryStream()){serializer.Serialize(stream,scenario);stream.Position=0;loaded=(Scenario)serializer.Deserialize(stream);}Assert(loaded.Features.Select(f=>f.Type).SequenceEqual(scenario.Features.Select(f=>f.Type)),"Multiple feature types and order survive save/reload");var backend=new FakeBackend();FeatureRunner.Run(loaded,backend);Assert(backend.Log.SequenceEqual(new[]{"speaker:0","speaker:1","speaker:2","mic:0","mic:1","mic:2","PlayMedia","NextMedia","PauseMedia","PreviousMedia","Mute"}),"All seven feature types execute in configured order");
 backend=new FakeBackend();FeatureRunner.Run(new Scenario{Features=new List<ScenarioFeature>{A(FeatureType.NextMedia),A(FeatureType.NextMedia)}},backend);Assert(backend.Lists==0&&backend.Log.Count==2,"Media-only scenario needs no audio devices and permits repeated actions");
 backend=new FakeBackend();FeatureRunner.Run(new Scenario{Features=new List<ScenarioFeature>{A(FeatureType.Output,"speaker")}},backend);Assert(backend.Lists==1&&backend.Defaults[1,0]=="in0"&&backend.Defaults[1,2]=="in2","Output-only scenario leaves all input roles untouched");
 backend=new FakeBackend();try{FeatureRunner.Run(new Scenario{Features=new List<ScenarioFeature>{A(FeatureType.PlayMedia),A(FeatureType.Input,"missing")}},backend);throw new Exception("Expected rejection");}catch(Exception ex){Assert(ex.Message.Contains("disconnected")&&backend.Log.Count==0,"Disconnected device prevents any feature from executing");}
 backend=new FakeBackend{FailId="mic"};try{FeatureRunner.Run(new Scenario{Features=new List<ScenarioFeature>{A(FeatureType.Output,"speaker"),A(FeatureType.Input,"mic")}},backend);throw new Exception("Expected rollback");}catch(Exception ex){Assert(ex.Message.Contains("restored")&&backend.Defaults[0,0]=="out0"&&backend.Defaults[0,2]=="out2"&&backend.Defaults[1,2]=="in2","Partial switching failure restores original defaults");}
 using(var receiver=new Receiver()){var handle=receiver.Handle;foreach(var pair in new[]{new[]{(int)FeatureType.PlayMedia,14},new[]{(int)FeatureType.PauseMedia,14},new[]{(int)FeatureType.NextMedia,11},new[]{(int)FeatureType.PreviousMedia,12}}){Media.SendTo(handle,(FeatureType)pair[0]);Assert(receiver.Command==pair[1],"Windows media message dispatch: "+((FeatureType)pair[0]));}}
 bool muted=Audio.IsMuted();Audio.SetMuted(muted);Assert(Audio.IsMuted()==muted,"Native audio mute API preserves and verifies current state");
 using(var editor=new Editor(scenario,new List<Scenario>{scenario})){editor.Show();Application.DoEvents();var selectors=(List<FeatureRow>)typeof(Editor).GetField("featureSelectors",F).GetValue(editor);Assert(selectors.Count==7,"Editor loads all saved feature rows");Assert(selectors[0].TypeSelector.Items.Count==6,"Feature dropdown offers Output, Input, toggle playback, next, previous and mute");selectors[0].TypeSelector.SelectedIndex=(int)FeatureType.PauseMedia;Application.DoEvents();Assert(!selectors[0].DeviceSelector.Visible&&selectors[0].Value.DeviceId=="","Changing to media hides and clears device choice");selectors[0].TypeSelector.SelectedIndex=(int)FeatureType.Output;Application.DoEvents();Assert(selectors[0].DeviceSelector.Visible&&selectors[0].Complete,"Choosing Output restores available device dropdown");typeof(Editor).GetMethod("AddFeature",F).Invoke(editor,new object[]{null});Application.DoEvents();Assert(selectors.Count==8&&!selectors.Last().Complete,"Add another feature creates a new unselected row");var last=selectors.Last();last.Controls.OfType<Button>().Single().PerformClick();Application.DoEvents();Assert(selectors.Count==7,"Remove deletes a feature row");using(var b=new Bitmap(editor.Width,editor.Height)){editor.DrawToBitmap(b,new Rectangle(Point.Empty,editor.Size));b.Save("features-editor.png");}editor.Close();}
 var mediaOnly=new Scenario{Name="Pause only",Features=new List<ScenarioFeature>{A(FeatureType.PauseMedia)}};using(var editor=new Editor(mediaOnly,new List<Scenario>{mediaOnly})){typeof(Editor).GetMethod("Save",F).Invoke(editor,new object[]{null,EventArgs.Empty});Assert(editor.Result!=null&&editor.Result.Features.Count==1&&editor.Result.Features[0].Type==FeatureType.PlayPauseMedia&&editor.Result.Output==""&&editor.Result.Input=="","Editor saves media-only scenarios without requiring audio devices");}
 using(var editor=new Editor(null,new List<Scenario>())){editor.Show();Application.DoEvents();var list=(List<FeatureRow>)typeof(Editor).GetField("featureSelectors",F).GetValue(editor);Assert(list.Count==0,"New scenarios start ready for Add a feature");editor.Close();}
 }
}





